import requests

PARTNER = "https://records.partner.example/store"

def store_record_bad(record: dict):
    # VULNERABLE: follows any redirect, no timeout, trusts whatever comes back
    r = requests.post(PARTNER, json=record)
    return r.json()

def store_record(record: dict):
    r = requests.post(PARTNER, json=record, timeout=5,
                      allow_redirects=False)       # a 3xx is an error here
    if r.status_code != 200:
        raise RuntimeError(f"partner returned {r.status_code}")
    data = r.json()
    if not isinstance(data.get("id"), str) or len(data["id"]) > 64:
        raise ValueError("unexpected partner response")  # validate like user input
    return {"id": data["id"]}                      # keep only what you need

