import base64, hashlib, hmac, secrets

def b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

def new_verifier() -> str:
    # 32 random bytes become 43 base64url characters (RFC 7636, section 4.1)
    return b64url(secrets.token_bytes(32))

def s256(verifier: str) -> str:
    # code_challenge = BASE64URL(SHA256(ASCII(code_verifier)))
    return b64url(hashlib.sha256(verifier.encode("ascii")).digest())

# 1. Client, before redirecting: keep the verifier, send only the challenge
verifier = new_verifier()
challenge = s256(verifier)
print(len(verifier), len(challenge))          # 43 43

# 2. Authorization server, at the token endpoint: recompute and compare
def check(stored_challenge: str, presented_verifier: str) -> bool:
    return hmac.compare_digest(s256(presented_verifier), stored_challenge)

print(check(challenge, verifier))             # True: the real client
print(check(challenge, new_verifier()))       # False: a thief with only the code

# The worked example from RFC 7636, Appendix B
print(s256("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"))
# E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM

