ALLOWED_ALGS = {"RS256"}
ISSUER = "https://auth.example.com"
AUDIENCE = "https://api.example.com"
LEEWAY = 30  # seconds

def validate(header, claims, signature_ok, now):
    if header.get("alg") not in ALLOWED_ALGS:
        return "reject: algorithm"
    if not signature_ok:              # checked with the issuer's key for kid
        return "reject: signature"
    if claims.get("iss") != ISSUER:
        return "reject: issuer"
    aud = claims.get("aud")
    auds = aud if isinstance(aud, list) else [aud]
    if AUDIENCE not in auds:
        return "reject: audience"
    if "exp" not in claims or now >= claims["exp"] + LEEWAY:
        return "reject: expired"
    if now < claims.get("nbf", 0) - LEEWAY:
        return "reject: not yet valid"
    return "accept: " + claims["sub"]

from functools import wraps
import jwt
from flask import Flask, abort, g, jsonify, request

ISSUER = "https://auth.example.com"
AUDIENCE = "https://api.example.com"
jwks = jwt.PyJWKClient(ISSUER + "/.well-known/jwks.json")

def require_scope(scope):
    def decorator(view):
        @wraps(view)
        def wrapper(*args, **kwargs):
            auth = request.headers.get("Authorization", "")
            if not auth.startswith("Bearer "):
                abort(401)
            token = auth.removeprefix("Bearer ")
            try:
                key = jwks.get_signing_key_from_jwt(token).key
                claims = jwt.decode(token, key, algorithms=["RS256"],
                                    audience=AUDIENCE, issuer=ISSUER, leeway=30,
                                    options={"require": ["exp", "iss", "aud", "sub"]})
            except jwt.PyJWTError:
                abort(401)                     # bad, expired or foreign token
            if scope not in claims.get("scope", "").split():
                abort(403)                     # valid token, not allowed this
            g.user = claims["sub"]
            return view(*args, **kwargs)
        return wrapper
    return decorator

app = Flask(__name__)

@app.get("/orders")
@require_scope("orders:read")
def orders():
    return jsonify(user=g.user, orders=[])  # then check each object's owner

import express from "express";
import { createRemoteJWKSet, jwtVerify } from "jose";

const ISSUER = "https://auth.example.com";
const AUDIENCE = "https://api.example.com";
const JWKS = createRemoteJWKSet(new URL(ISSUER + "/.well-known/jwks.json"));

async function requireToken(req, res, next) {
  const [scheme, token] = (req.get("Authorization") || "").split(" ");
  if (scheme !== "Bearer" || !token) {
    return res.status(401).set("WWW-Authenticate", "Bearer").end();
  }
  try {
    const { payload } = await jwtVerify(token, JWKS, {
      issuer: ISSUER,              // iss must match exactly
      audience: AUDIENCE,          // aud must include this API
      algorithms: ["RS256"],       // pinned
      requiredClaims: ["exp", "sub"],
      clockTolerance: 30,          // seconds of skew for exp and nbf
    });
    req.user = payload.sub;
    req.scopes = String(payload.scope || "").split(" ");
    return next();
  } catch {
    return res.status(401)
      .set("WWW-Authenticate", 'Bearer error="invalid_token"').end();
  }
}

const app = express();
app.get("/orders", requireToken, (req, res) => {
  if (!req.scopes.includes("orders:read")) return res.status(403).end();
  res.json({ user: req.user, orders: [] });   // then per-object checks
});

import base64, hashlib, hmac, json
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding

def b64d(s): return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))

def verify_bad(token: str, public_pem: bytes) -> dict:
    h64, p64, s64 = token.split(".")
    alg = json.loads(b64d(h64))["alg"]      # chosen by whoever made the token
    data = (h64 + "." + p64).encode()
    if alg == "RS256":
        key = serialization.load_pem_public_key(public_pem)
        key.verify(b64d(s64), data, padding.PKCS1v15(), hashes.SHA256())
    elif alg == "HS256":                     # same bytes reused as an HMAC secret
        mac = hmac.new(public_pem, data, hashlib.sha256).digest()
        if not hmac.compare_digest(mac, b64d(s64)):
            raise ValueError("bad signature")
    elif alg == "none":
        pass                                 # no signature checked at all
    else:
        raise ValueError("unknown alg")
    return json.loads(b64d(p64))

# A JWT cannot be "deleted", so an API that must cut one off early keeps a
# short denylist of revoked token ids (jti). Entries can be dropped once the
# token would have expired anyway, so the list stays small if lifetimes are short.
REVOKED = {}   # jti maps to the token's exp

def revoke(claims):
    REVOKED[claims["jti"]] = claims["exp"]

def is_revoked(claims, now):
    for jti, exp in list(REVOKED.items()):
        if exp <= now:
            del REVOKED[jti]              # expired: exp check rejects it anyway
    return claims.get("jti") in REVOKED

stolen = {"jti": "a1f3", "sub": "user-42", "exp": 1763000900}
other = {"jti": "9bc2", "sub": "user-7", "exp": 1763000900}
revoke(stolen)
print(is_revoked(stolen, now=1763000100))   # True: refuse it now
print(is_revoked(other, now=1763000100))    # False
print(is_revoked(stolen, now=1763001000), len(REVOKED))  # False 0 (expired)

import json
from collections import Counter

RETIRED_KIDS = {"2016-consumer"}
ALWAYS_ALERT = {"alg_not_allowed", "refresh_reuse", "retired_kid"}

def alerts(lines, max_rejects=20):
    rejects = Counter()
    for line in lines:
        e = json.loads(line)
        if e.get("kid") in RETIRED_KIDS:
            e["result"] = "retired_kid"          # signed by a key that should be dead
        if e["result"] in ALWAYS_ALERT:
            yield f"ALERT {e['result']} client={e['client']} ip={e['ip']}"
        elif e["result"] != "ok":
            rejects[e["client"]] += 1
            if rejects[e["client"]] == max_rejects:
                yield f"ALERT {max_rejects} rejected tokens from client={e['client']}"

log = [
  '{"client":"web","ip":"203.0.113.9","kid":"k7","result":"ok"}',
  '{"client":"web","ip":"198.51.100.4","kid":null,"result":"alg_not_allowed"}',
  '{"client":"mobile","ip":"192.0.2.1","kid":"2016-consumer","result":"ok"}',
  '{"client":"cli","ip":"192.0.2.77","kid":"k7","result":"refresh_reuse"}',
] + ['{"client":"bot","ip":"192.0.2.5","kid":"k7","result":"bad_audience"}'] * 20
for a in alerts(log):
    print(a)
